// Parse DocuSign Connect webhook payload
// DocuSign sends JSON Connect events
const body = $input.first().json.body || $input.first().json;

let envelopeId, status, completedAt;

if (body.event) {
  // JSON Connect payload
  envelopeId  = body.data?.envelopeId || body.envelopeId;
  status      = body.event;
  completedAt = body.data?.envelopeSummary?.completedDateTime || new Date().toISOString();
} else if (body.EnvelopeStatus) {
  // Legacy XML-parsed payload
  envelopeId  = body.EnvelopeID || body.EnvelopeId;
  status      = body.EnvelopeStatus;
  completedAt = body.Completed || new Date().toISOString();
} else {
  envelopeId  = body.envelopeId || body.envelope_id;
  status      = body.status || body.event || '';
  completedAt = body.completedDateTime || new Date().toISOString();
}

const isSigned   = ['envelope-completed', 'envelope-signed', 'Completed', 'completed'].includes(status);
const isDeclined = ['envelope-declined',  'envelope-voided', 'Declined',  'declined'].includes(status);

if (!envelopeId) throw new Error('No envelopeId in DocuSign payload: ' + JSON.stringify(body));

return [{ json: { envelopeId, status, isSigned, isDeclined, completedAt } }];

// Find ticket via trace_log notes (envelopeId was stored in notes by docusign_sign workflow)
// trace_log has NO ticket_id column — it uses decision_id
// We find the ticket by looking up the decision that references the envelope
const POSTGREST = $env.POSTGREST_URL || 'https://postgrest-production-7960.up.railway.app';
const JWT = $env.POSTGREST_JWT;

const { envelopeId, completedAt } = $input.first().json;

// Find trace entry containing the envelopeId in notes — get decision_id from it
const traceRes = await this.helpers.httpRequest({
  method: 'GET',
  url: POSTGREST + '/trace_log?notes=ilike.*' + envelopeId + '*&order=created_at.desc&limit=1',
  headers: { 'Authorization': 'Bearer ' + JWT, 'Accept': 'application/json' }
});

const trace = traceRes[0];
if (!trace) throw new Error('No trace found for envelope: ' + envelopeId);

// Get ticket_id from the decision that owns this trace entry
let ticketId = null;
if (trace.decision_id) {
  const decRes = await this.helpers.httpRequest({
    method: 'GET',
    url: POSTGREST + '/decisions?id=eq.' + trace.decision_id + '&select=ticket_id',
    headers: { 'Authorization': 'Bearer ' + JWT, 'Accept': 'application/json' }
  });
  ticketId = decRes[0]?.ticket_id;
}

// Fallback: parse ticket_id from the trace value field
if (!ticketId) {
  const match = (trace.value || '').match(/ticket\s+([0-9a-f-]{36})/i);
  ticketId = match ? match[1] : null;
}

if (!ticketId) throw new Error('Could not resolve ticket_id for envelope: ' + envelopeId);

// Update ticket status → approved
await this.helpers.httpRequest({
  method: 'PATCH',
  url: POSTGREST + '/tickets?id=eq.' + ticketId,
  headers: { 'Authorization': 'Bearer ' + JWT, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
  body: JSON.stringify({ status: 'approved' })
});

// Update legal_document signed_at — linked via supplier_id, find by supplier from ticket
const ticketRes = await this.helpers.httpRequest({
  method: 'GET',
  url: POSTGREST + '/tickets?id=eq.' + ticketId + '&select=supplier_id',
  headers: { 'Authorization': 'Bearer ' + JWT, 'Accept': 'application/json' }
});
const supplierId = ticketRes[0]?.supplier_id;
if (supplierId) {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: POSTGREST + '/legal_documents?supplier_id=eq.' + supplierId + '&status=in.(draft,pending_signature)',
    headers: { 'Authorization': 'Bearer ' + JWT, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
    body: JSON.stringify({ status: 'signed', signed_at: completedAt })
  });
}

// Write trace entry (no ticket_id FK on trace_log — use decision_id if available)
await this.helpers.httpRequest({
  method: 'POST',
  url: POSTGREST + '/trace_log',
  headers: { 'Authorization': 'Bearer ' + JWT, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
  body: JSON.stringify({
    decision_id: trace.decision_id || null,
    signal: 'contract',
    value: 'Envelope ' + envelopeId + ' signed. Ticket ' + ticketId + ' approved.',
    green: true,
    weight: 1.0,
    notes: 'DocuSign envelope ' + envelopeId + ' completed at ' + completedAt + '.'
  })
});

return [{ json: { ticketId, envelopeId, result: 'signed' } }];

// Declined — log to trace, no ticket status change
const POSTGREST = $env.POSTGREST_URL || 'https://postgrest-production-7960.up.railway.app';
const JWT = $env.POSTGREST_JWT;

const { envelopeId, status } = $input.first().json;

const traceRes = await this.helpers.httpRequest({
  method: 'GET',
  url: POSTGREST + '/trace_log?notes=ilike.*' + envelopeId + '*&order=created_at.desc&limit=1',
  headers: { 'Authorization': 'Bearer ' + JWT, 'Accept': 'application/json' }
});

const trace = traceRes[0];
if (!trace) return [{ json: { skipped: true, reason: 'no trace for ' + envelopeId } }];

await this.helpers.httpRequest({
  method: 'POST',
  url: POSTGREST + '/trace_log',
  headers: { 'Authorization': 'Bearer ' + JWT, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
  body: JSON.stringify({
    decision_id: trace.decision_id || null,
    signal: 'contract',
    value: 'Envelope ' + envelopeId + ' declined.',
    green: false,
    weight: 1.0,
    notes: 'DocuSign envelope ' + envelopeId + ' declined/voided. Status: ' + status
  })
});

return [{ json: { envelopeId, result: 'declined' } }];
